const body = $input.first().json.body || {};
const token = body.t || '';
const url = body.url || '';

// Lấy database lưu token tạo link
const db = $getWorkflowStaticData('global');
const session = db.linkSessions ? db.linkSessions[token] : null;

let html = '';
let isValid = false;

if (!session) {
  html = `<h2>❌ Liên kết không hợp lệ.</h2>`;
} else if (Date.now() > session.expires_at) {
  html = `<h2>⏱ Đã hết hạn. Vui lòng tạo link mới trong Zalo.</h2>`;
} else {
  isValid = true;
  session.used = true; // Đánh dấu đã sử dụng
  html = `<!DOCTYPE html><html lang="vi"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thành công</title><style>body{font-family:Arial,sans-serif;background:#f5f5f5;text-align:center;padding:50px 20px;} .box{max-width:400px;margin:auto;background:#fff;padding:30px;border-radius:15px;box-shadow:0 4px 15px rgba(0,0,0,0.1);}</style></head><body><div class="box"><h2 style="color:#128C4A;">✅ Đã nhận link!</h2><p>Hệ thống đang xử lý, vui lòng quay lại <b>Zalo</b> để nhận link Affiliate nhé.</p></div></body></html>`;
}

return [{
  json: {
    isValid,
    html,
    session,
    url
  }
}];

const src = $input.first().json;

// Nếu session không hợp lệ, ngừng xử lý
if (!src.isValid) return [];

// Giả lập Payload giống hệt Zalo gửi đến
return [{
  json: {
    headers: {
      // Lưu ý: Chuỗi này phải khớp với webhookSecret trong node Config + Router
      'x-bot-api-secret-token': 'ZaloShopee2026ABC789' 
    },
    body: {
      message: {
        text: src.url,
        chat: { id: src.session.chat_id },
        from: {
          id: src.session.user_id,
          display_name: src.session.display_name
        }
      }
    }
  }
}];
